-- SELECT-only prerequisite inventory. No operational login, RPC, repair or apply.
-- Run only against independently verified Field Manual otnhhdxstdnwccehacku.
BEGIN TRANSACTION READ ONLY;
SET LOCAL statement_timeout='20s';
SELECT jsonb_build_object('database',current_database(),'session_user',session_user,'role',current_user,'captured_at',transaction_timestamp(),'read_only',current_setting('transaction_read_only')) AS identity;
SELECT jsonb_agg(jsonb_build_object('version',version,'name',name,'statement_count',cardinality(statements),'statement_array_sha256',encode(extensions.digest(convert_to(to_jsonb(statements)::text,'UTF8'),'sha256'),'hex')) ORDER BY version) AS ledger FROM supabase_migrations.schema_migrations;
SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'oid',p.oid,'owner',pg_get_userbyid(p.proowner),'acl',p.proacl,'security_definer',p.prosecdef,'config',p.proconfig,'body_sha256',encode(extensions.digest(convert_to(p.prosrc,'UTF8'),'sha256'),'hex')) ORDER BY p.oid::regprocedure::text) AS functions FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind='f';
SELECT jsonb_agg(jsonb_build_object('table',t,'exists',to_regclass('public.'||t) IS NOT NULL) ORDER BY t) AS new_tables FROM unnest(ARRAY['athlete_training_setup','private_programme_alpha_eligibility','athlete_running_zone2_inputs','programme_occurrence_zone2_targets','athlete_running_quality_inputs']) t;
SELECT jsonb_build_object('completion_receipt_column',EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='programme_slot_outcomes' AND column_name='completion_request_sha256'),'extensions_digest',to_regprocedure('extensions.digest(bytea,text)') IS NOT NULL,'training_timezone',EXISTS(SELECT 1 FROM pg_timezone_names WHERE name='Asia/Makassar')) AS prerequisites;
SELECT jsonb_agg(jsonb_build_object('table',c.relname,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl) ORDER BY c.relname) AS table_authorities FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='r';
SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'owner',pg_get_userbyid(d.defaclrole),'kind',d.defaclobjtype,'acl',d.defaclacl) ORDER BY n.nspname,d.defaclrole,d.defaclobjtype) AS default_acls FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace;
SELECT jsonb_agg(to_jsonb(p) ORDER BY p.tablename,p.policyname) AS policies FROM pg_policies p WHERE p.schemaname='public';
SELECT jsonb_agg(jsonb_build_object('table',t.tgrelid::regclass::text,'name',t.tgname,'definition',pg_get_triggerdef(t.oid)) ORDER BY t.tgrelid::regclass::text,t.tgname) AS triggers FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND NOT t.tgisinternal;
SELECT jsonb_build_object('candidate_version_rows',(SELECT count(*) FROM public.programme_versions WHERE id='b0290b33-2764-4e5b-ad78-3d4beafbb375'),'candidate_lineage_rows',(SELECT count(*) FROM public.programme_lineages WHERE code='HYBRID10K-GENERAL-DRAFT'),'catalogue_rows',(SELECT count(*) FROM public.exercises_v2)) AS collisions;
COMMIT;
